import sqlite3
import json

conn = sqlite3.connect('/root/data/eventlogs.db')
conn.row_factory = sqlite3.Row
cur = conn.cursor()

cur.execute("SELECT * FROM events")
all_events = [dict(r) for r in cur.fetchall()]

# Malicious Process PIDs
mal_pids = {3356, 3148, 4288, 6208, 2368}
mal_hex_pids = {'0xd1c', '0xc4c', '0x10c0', '0x1840', '0x940'}

# Let's inspect Registry events (12, 13)
print("\n--- Registry Events ---")
for e in all_events:
    if e['event_code'] in (12, 13) and e['host'] == 'WS-05.corp.example':
        # Let's see which ones are related to our malicious processes or PIDs
        msg = (e['message'] or '').lower()
        # Is it related?
        is_rel = False
        for hp in mal_hex_pids:
            if hp in msg:
                is_rel = True
        guid = (e['process_guid'] or '').lower()
        if guid in {'{71b87c12-d7e5-5f84-0d01-000000000500}', '{71b87c12-d9fe-5f84-1701-000000000500}', '{71b87c12-d9fe-5f84-1801-000000000500}', '{71b87c12-d9fe-5f84-1901-000000000500}', '{71b87c12-d9fe-5f84-1a01-000000000500}'}:
            is_rel = True

        if is_rel:
            print(f"{e['event_id']} | EC: {e['event_code']} | Image: {e['image']} | Target: {e['target_object']} | Details: {e['details']}")

# Let's inspect Handle/Resource Access events (4656, 4663, 4658, 4690)
print("\n--- Handle/Resource Access Events ---")
for e in all_events:
    if e['event_code'] in (4656, 4663, 4658, 4690) and e['host'] == 'WS-05.corp.example':
        msg = (e['message'] or '').lower()
        is_rel = False
        matched_pid = None
        for hp in mal_hex_pids:
            if hp in msg:
                is_rel = True
                matched_pid = hp

        if is_rel:
            # Print brief details
            print(f"{e['event_id']} | EC: {e['event_code']} | ProcessId: {matched_pid} | Message snippet: {e['message'][:120].replace('\n', ' ')}")

